-- NC-4: Add Mahesh Ganorkar as R nominee
UPDATE house_races SET candidate2_name = 'Mahesh Ganorkar', candidate2_party = 'R' WHERE state_code = 'NC' AND district = 4;

-- NC-7: Add Kimberly Hardy as D nominee
UPDATE house_races SET candidate1_name = 'Kimberly Hardy', candidate1_party = 'D' WHERE state_code = 'NC' AND district = 7;

-- OH-1: Add Eric Conroy as R nominee
UPDATE house_races SET candidate2_name = 'Eric Conroy', candidate2_party = 'R' WHERE state_code = 'OH' AND district = 1;

-- PA-1: Fix D nominee to Bob Harvie (not Brian Harvie)
UPDATE house_races SET candidate1_name = 'Bob Harvie', candidate1_party = 'D' WHERE state_code = 'PA' AND district = 1;

-- PA-2: Add Jessica Arriaga as R nominee
UPDATE house_races SET candidate2_name = 'Jessica Arriaga', candidate2_party = 'R' WHERE state_code = 'PA' AND district = 2;

-- PA-4: Add Aurora Stuski as R nominee
UPDATE house_races SET candidate2_name = 'Aurora Stuski', candidate2_party = 'R' WHERE state_code = 'PA' AND district = 4;

-- PA-5: Add Nick Manganaro as R nominee
UPDATE house_races SET candidate2_name = 'Nick Manganaro', candidate2_party = 'R' WHERE state_code = 'PA' AND district = 5;

-- PA-6: Add Marty Young as R nominee
UPDATE house_races SET candidate2_name = 'Marty Young', candidate2_party = 'R' WHERE state_code = 'PA' AND district = 6;

-- PA-7: Add Bob Brooks as D nominee
UPDATE house_races SET candidate1_name = 'Bob Brooks', candidate1_party = 'D' WHERE state_code = 'PA' AND district = 7;

-- PA-8: Add Paige Cognetti as D nominee
UPDATE house_races SET candidate1_name = 'Paige Cognetti', candidate1_party = 'D' WHERE state_code = 'PA' AND district = 8;

-- PA-9: Add Rachel Wallace as D nominee
UPDATE house_races SET candidate1_name = 'Rachel Wallace', candidate1_party = 'D' WHERE state_code = 'PA' AND district = 9;

-- PA-10: Add Janelle Stelson as D nominee
UPDATE house_races SET candidate1_name = 'Janelle Stelson', candidate1_party = 'D' WHERE state_code = 'PA' AND district = 10;

-- PA-3: Confirm no R candidate (correct as-is, no update needed)
-- CA-1: Need to check D candidate separately

SELECT state_code, district, candidate1_name, candidate1_party, candidate2_name, candidate2_party, status
FROM house_races
WHERE (state_code = 'NC' AND district IN (4,7))
   OR (state_code = 'OH' AND district = 1)
   OR (state_code = 'PA' AND district IN (1,2,4,5,6,7,8,9,10))
ORDER BY state_code, district;

